<?php require 'config/database.php';require 'helpers/functions.php';login_required();$s=$pdo->query('SELECT COUNT(*) products,COALESCE(SUM(stock),0) units,COALESCE(SUM(stock*price),0) value FROM products')->fetch();$m=$pdo->query('SELECT type,SUM(quantity) total FROM stock_movements GROUP BY type')->fetchAll();$tot=['IN'=>0,'OUT'=>0];foreach($m as $r)$tot[$r['type']]=(int)$r['total'];$rows=$pdo->query('SELECT c.name,COUNT(p.id) products,COALESCE(SUM(p.stock),0) units,COALESCE(SUM(p.stock*p.price),0) value FROM categories c LEFT JOIN products p ON p.category_id=c.id GROUP BY c.id')->fetchAll();header_html('Laporan');echo '<section class="stats"><div><small>Produk</small><h2>'.e($s['products']).'</h2></div><div><small>Total unit</small><h2>'.e($s['units']).'</h2></div><div><small>Nilai persediaan</small><h2>Rp '.number_format((float)$s['value'],0,',','.').'</h2></div><div><small>Masuk / Keluar</small><h2>'.$tot['IN'].' / '.$tot['OUT'].'</h2></div></section><section><h2>Ringkasan kategori</h2><table><tr><th>Kategori</th><th>Produk</th><th>Unit</th><th>Nilai</th></tr>';foreach($rows as $r)echo '<tr><td>'.e($r['name']).'</td><td>'.e($r['products']).'</td><td>'.e($r['units']).'</td><td>Rp '.number_format((float)$r['value'],0,',','.').'</td></tr>';echo '</table></section>';footer_html();